program = '''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    sep_rows = [r for r, row in enumerate(g) if row[0] != 0 and all(v == row[0] for v in row)]
    sep_cols = [c for c in range(w) if g[0][c] != 0 and all(g[r][c] == g[0][c] for r in range(h))]
    row_ranges = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))
    col_ranges = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))
    tiles = [[g[r0:r1] for r0,r1 in row_ranges] for _ in []]
    colors = {v for row in g for v in row} - {0} - {g[sep_rows[0]][0] if sep_rows else -1}
    nr, nc = len(row_ranges), len(col_ranges)
    def has_color(tr, tc, color):
        r0,r1 = row_ranges[tr]; c0,c1 = col_ranges[tc]
        return any(g[r][c] == color for r in range(r0,r1) for c in range(c0,c1))
    for color in colors:
        for tr in range(nr-1):
            for tc in range(nc-1):
                cells = [(tr,tc),(tr,tc+1),(tr+1,tc),(tr+1,tc+1)]
                occupied = [p for p in cells if has_color(*p,color)]
                if len(occupied) != 3:
                    continue
                missing = next(p for p in cells if p not in occupied)
                mr,mc = missing
                # Copy the adjacent tile in the missing row, reflected left-to-right.
                sr,sc = (mr, mc-1) if mc == tc+1 else (mr, mc+1)
                r0,r1 = row_ranges[sr]; c0,c1 = col_ranges[sc]
                dr0,dr1 = row_ranges[mr]; dc0,dc1 = col_ranges[mc]
                sh,sw = r1-r0,c1-c0
                dh,dw = dr1-dr0,dc1-dc0
                if (sh,sw) != (dh,dw):
                    continue
                for i in range(dh):
                    for j in range(dw):
                        v = g[r0+i][c1-1-j]
                        if v == color:
                            g[dr0+i][dc0+j] = color
    return g
'''
